#!/usr/bin/env python3
"""Focused syntax/semantic check for the ported u32_set_parms().

Run from a checkout root (e.g. the validation temp clone). It extracts the
actual u32_set_parms() body from net/sched/cls_u32.c and compiles it inside a
stub translation unit with `-Wall -Wextra -Werror` both with and without
CONFIG_NET_CLS_IND. This verifies brace/#ifdef balance and that `ifindex` is
declared and consumed without warnings in either configuration.

It is a supplemental check: the full kernel build is unavailable in this
environment (no `make`, no generated build headers).
"""
import os
import shutil
import subprocess
import sys
import tempfile

CC = shutil.which("gcc-10") or shutil.which("gcc") or shutil.which("cc")
SRC = "net/sched/cls_u32.c"

STUBS = r'''#include <stddef.h>
typedef unsigned int u32;
typedef int bool;
#define true 1
#define false 0
#define EINVAL 22
struct net;
struct tcf_proto;
struct nlattr;
struct netlink_ext_ack;
struct tc_u_common { int x; };
struct tc_u_hnode { u32 handle; int refcnt; struct tc_u_common *tp_c; };
struct tcf_exts { int x; };
struct tcf_result { u32 classid; unsigned long class; };
struct tc_u_knode {
	int pad0;
	struct tcf_exts exts;
#ifdef CONFIG_NET_CLS_IND
	int ifindex;
#endif
	struct tcf_result res;
	struct tc_u_hnode *ht_down;
};
#define TCA_U32_LINK 1
#define TCA_U32_CLASSID 2
