def extract_func(text):
    lines = text.splitlines()
    start = None
    for i, line in enumerate(lines):
        if line.startswith("static int u32_set_parms("):
            start = i
            break
    if start is None:
        raise SystemExit("u32_set_parms not found in %s" % SRC)
    j = start
    while "{" not in lines[j]:
        j += 1
    depth = 0
    for k in range(j, len(lines)):
        depth += lines[k].count("{") - lines[k].count("}")
        if depth == 0:
            return "\n".join(lines[start:k + 1])
    raise SystemExit("unbalanced u32_set_parms braces")


def main():
    if not CC:
        print("no C compiler available", file=sys.stderr)
        return 2
    src = open(SRC, encoding="utf-8").read()
    func = extract_func(src)
    harness = STUBS + func + "\n"
    rc = 0
    with tempfile.TemporaryDirectory() as tmp:
        path = os.path.join(tmp, "harness.c")
        open(path, "w", encoding="utf-8").write(harness)
        for label, extra in (("with-CONFIG_NET_CLS_IND", ["-DCONFIG_NET_CLS_IND"]),
