#!/usr/bin/env python3
"""Focused syntax/semantic check for the ported u32_set_parms().

Run from a checkout root (e.g. the validation temp clone). It extracts the
actual u32_set_parms() body from net/sched/cls_u32.c and compiles it inside a
stub translation unit with `-Wall -Wextra -Werror` both with and without
CONFIG_NET_CLS_IND. This verifies brace/#ifdef balance and that `ifindex` is
declared and consumed without warnings in either configuration.

It is a supplemental check: the full kernel build is unavailable in this
environment (no `make`, no generated build headers).
"""
import os
import shutil
import subprocess
import sys
import tempfile

CC = shutil.which("gcc-10") or shutil.which("gcc") or shutil.which("cc")
SRC = "net/sched/cls_u32.c"

STUBS = r'''#include <stddef.h>
typedef unsigned int u32;
typedef int bool;
#define true 1
#define false 0
#define EINVAL 22
struct net;
struct tcf_proto;
struct nlattr;
struct netlink_ext_ack;
struct tc_u_common { int x; };
struct tc_u_hnode { u32 handle; int refcnt; struct tc_u_common *tp_c; };
struct tcf_exts { int x; };
struct tcf_result { u32 classid; unsigned long class; };
struct tc_u_knode {
	int pad0;
	struct tcf_exts exts;
#ifdef CONFIG_NET_CLS_IND
	int ifindex;
#endif
	struct tcf_result res;
	struct tc_u_hnode *ht_down;
};
#define TCA_U32_LINK 1
#define TCA_U32_CLASSID 2
#define TCA_U32_INDEV 3
#define TC_U32_KEY(h) 0
#define NL_SET_ERR_MSG_MOD(e, m) do { (void)(e); } while (0)
#define rtnl_dereference(p) (p)
#define rcu_assign_pointer(p, v) do { (p) = (v); } while (0)
static inline u32 nla_get_u32(struct nlattr *a) { (void)a; return 0; }
static int tcf_exts_validate(struct net *n, struct tcf_proto *t, struct nlattr **tb,
			     struct nlattr *e, struct tcf_exts *x, bool ovr,
			     struct netlink_ext_ack *ex)
{ (void)n;(void)t;(void)tb;(void)e;(void)x;(void)ovr;(void)ex; return 0; }
static struct tc_u_hnode *u32_lookup_ht(struct tc_u_common *c, u32 h)
{ (void)c;(void)h; return 0; }
static void tcf_bind_filter(struct tcf_proto *tp, struct tcf_result *r, unsigned long b)
{ (void)tp;(void)r;(void)b; }
#ifdef CONFIG_NET_CLS_IND
static int tcf_change_indev(struct net *n, struct nlattr *a, struct netlink_ext_ack *e)
{ (void)n;(void)a;(void)e; return 0; }
#endif
'''


def extract_func(text):
    lines = text.splitlines()
    start = None
    for i, line in enumerate(lines):
        if line.startswith("static int u32_set_parms("):
            start = i
            break
    if start is None:
        raise SystemExit("u32_set_parms not found in %s" % SRC)
    j = start
    while "{" not in lines[j]:
        j += 1
    depth = 0
    for k in range(j, len(lines)):
        depth += lines[k].count("{") - lines[k].count("}")
        if depth == 0:
            return "\n".join(lines[start:k + 1])
    raise SystemExit("unbalanced u32_set_parms braces")


def main():
    if not CC:
        print("no C compiler available", file=sys.stderr)
        return 2
    src = open(SRC, encoding="utf-8").read()
    func = extract_func(src)
    harness = STUBS + func + "\n"
    rc = 0
    with tempfile.TemporaryDirectory() as tmp:
        path = os.path.join(tmp, "harness.c")
        open(path, "w", encoding="utf-8").write(harness)
        for label, extra in (("with-CONFIG_NET_CLS_IND", ["-DCONFIG_NET_CLS_IND"]),
                             ("without-CONFIG_NET_CLS_IND", [])):
            proc = subprocess.run(
                [CC, "-std=gnu89", "-Wall", "-Wextra", "-Werror", "-fsyntax-only", *extra, path],
                capture_output=True, text=True)
            print("[%s] exit=%d" % (label, proc.returncode))
            sys.stdout.write(proc.stdout)
            sys.stderr.write(proc.stderr)
            if proc.returncode != 0:
                rc = 1
    return rc


if __name__ == "__main__":
    raise SystemExit(main())

diff --git a/net/sched/cls_u32.c b/net/sched/cls_u32.c
index d30256ac3537..ee8ef606a8e9 100644
--- a/net/sched/cls_u32.c
+++ b/net/sched/cls_u32.c
@@ -778,11 +778,22 @@ static int u32_set_parms(struct net *net, struct tcf_proto *tp,
 			 struct netlink_ext_ack *extack)
 {
 	int err;
+#ifdef CONFIG_NET_CLS_IND
+	int ifindex = -1;
+#endif

 	err = tcf_exts_validate(net, tp, tb, est, &n->exts, ovr, extack);
 	if (err < 0)
 		return err;

+#ifdef CONFIG_NET_CLS_IND
+	if (tb[TCA_U32_INDEV]) {
