  "reference_semantics": {
    "vulnerable_behavior": "u32_set_parms() 在 TCA_U32_LINK 分支中递增 ht_down->refcnt，并可能执行 tcf_bind_filter()；随后才在函数末尾调用 tcf_change_indev() 解析 TCA_U32_INDEV。一旦 tcf_change_indev() 返回负值（设备名不存在 -ENODEV 或名称超长 -EINVAL），函数直接 return -EINVAL，已递增的 ht_down->refcnt 不会回退。重复触发可令引用计数溢出，导致 hnode 被提前释放并产生 double free / use-after-free。",
    "trigger_condition": "具备 CAP_NET_ADMIN 的本地用户对已有 u32 过滤器发送 RTM_NEWTFILTER/RTM_DELTFILTER 变更请求，携带 TCA_U32_LINK（指向一个已存在的非根 hnode）以及无法解析的 TCA_U32_INDEV（不存在的网络设备名），使 tcf_change_indev 失败。",
    "security_invariants": [
      "任何会改变共享状态（ht_down->refcnt++、tcf_bind_filter）的操作必须在所有可失败的输入校验（TCA_U32_INDEV 解析）之后执行。",
      "校验失败路径不得留下未回滚的引用计数增量。"
    ],
    "sensitive_operations": [
      "ht_down->refcnt++ (net/sched/cls_u32.c:802)",
      "tcf_bind_filter() (813)",
      "tcf_change_indev() (819)",
      "return -EINVAL 失败路径 (821)"
    ]
  },
